if(g.mode==='training'){g.clock=60;if(g.e.hp<g.e.maxHp&&g.e.stun===0&&g.p.comboAge>1.5)g.e.hp=Math.min(g.e.maxHp,g.e.hp+dt*65);if(g.e.hp<=0){g.e.hp=g.e.maxHp;g.e.dot=0;g.e.stun=0;}g.p.hp=g.p.maxHp;g.p.meter=clamp(g.p.meter+dt*24,0,100);return;}
