let backgroundCache=null,cacheKey='';
function fitCanvas(c){const r=c.getBoundingClientRect(),d=Math.min(window.devicePixelRatio||1,2),w=Math.max(1,Math.round(r.width*d)),h=Math.max(1,Math.round(r.height*d));if(c.width!==w||c.height!==h){c.width=w;c.height=h;}return{w:r.width,h:r.height,d};}
function renderBattle(){if(!game)return;const g=game,c=$('battle'),{w:W,h:H,d}=fitCanvas(c),ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);const key=[W,H,g.arena.id,g.seed].join('-');if(cacheKey!==key){cacheKey=key;backgroundCache=document.createElement('canvas');backgroundCache.width=c.width;backgroundCache.height=c.height;const bc=backgroundCache.getContext('2d');bc.scale(d,d);drawArena(bc,W,H,g.arena,g.seed,0);}ctx.drawImage(backgroundCache,0,0,W,H);
const landscape=W>H,view=Math.max(landscape?1050:610,Math.abs(g.p.x-g.e.x)+240),sc=Math.min(W/view,H/340),mid=(g.p.x+g.e.x)/2,cam=view>=1000?500:clamp(mid,view/2,1000-view/2),floor=H*.75;ctx.save();const shake=settings.effects?g.shake:0;ctx.translate(W*.5-cam*sc+(Math.random()-.5)*shake,floor+(Math.random()-.5)*shake*.5);ctx.scale(sc,sc);
for(const f of [g.p,g.e]){ellipse(ctx,f.x,6,50-(Math.min(150,f.y)/8),8,'#020a13a8');}
for(const t of g.traps){ctx.save();ctx.globalAlpha=.5+Math.sin(time*15)*.3;ellipse(ctx,t.x,0,t.r,12,t.color+'40');ctx.beginPath();ctx.ellipse(t.x,0,t.r,12,0,0,Math.PI*2);ctx.strokeStyle=t.color;ctx.lineWidth=2;ctx.stroke();if(t.meteor){line(ctx,t.x,-280,t.x,0,t.color+'40',2);poly(ctx,[[t.x-8,-15],[t.x,-5],[t.x+8,-15]],t.color);}ctx.restore();}
for(const f of [g.e,g.p]){ctx.save();ctx.translate(f.x,-f.y);drawFighter(ctx,f,time,1);ctx.restore();if(f.dot>0){ellipse(ctx,f.x+22,-f.y-180,4,4,'#bce890');}if(f.slow>0||f.root>0){ring(ctx,f.x,-f.y-25,27,'#a4ddff88',2);}}
for(const b of g.beams){ctx.save();ctx.globalAlpha=clamp(b.life*5,0,1);line(ctx,b.x,-b.y,b.x+b.dir*b.len,-b.y,b.color+'44',22);line(ctx,b.x,-b.y,b.x+b.dir*b.len,-b.y,b.color,6);line(ctx,b.x,-b.y,b.x+b.dir*b.len,-b.y,'#fffbea',2);ctx.restore();}
for(const p of g.projectiles){ctx.save();ctx.translate(p.x,-p.y);const tail=-Math.sign(p.vx);poly(ctx,[[0,-p.r*.6],[tail*(30+p.r*2),0],[0,p.r*.6]],p.color+'70');const glow=ctx.createRadialGradient(0,0,1,0,0,p.r*2);glow.addColorStop(0,p.color+'99');glow.addColorStop(1,p.color+'00');ctx.fillStyle=glow;ctx.fillRect(-p.r*2,-p.r*2,p.r*4,p.r*4);ellipse(ctx,0,0,p.r,p.r*.78,p.color);ellipse(ctx,3,-3,p.r*.47,p.r*.4,'#fffae9');ctx.restore();}
for(const p of g.particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);line(ctx,p.x,-p.y,p.x-p.vx*.025,-p.y+p.vy*.025,p.color,p.r);}ctx.globalAlpha=1;
for(const r of g.rings){ctx.save();ctx.globalAlpha=clamp(r.life*2,0,1);ring(ctx,r.x,-r.y,r.r,r.color,4);ring(ctx,r.x,-r.y,r.r*.9,r.color+'55',1);ctx.restore();}
for(const l of g.labels){ctx.globalAlpha=clamp(l.life*2,0,1);ctx.fillStyle=l.color;ctx.font='800 20px system-ui';ctx.textAlign='center';ctx.fillText(l.text,l.x,-l.y);}ctx.restore();ctx.globalAlpha=1;
if(g.mod.fog){ctx.fillStyle='#bcd8d316';ctx.fillRect(0,H*.28,W,H*.6);}if(g.flash>0&&settings.effects){ctx.fillStyle='#d7ffff16';ctx.fillRect(0,0,W,H);}if(g.banner){ctx.save();ctx.textAlign='center';ctx.font='800 '+Math.max(13,W*.024)+'px system-ui';ctx.fillStyle=g.banner.color;ctx.fillText(g.banner.title,W/2,H*.29);ctx.restore();}
updateHUD();}
function portrait(h,w=160,hei=155){const c=document.createElement('canvas');c.width=w;c.height=hei;const ctx=c.getContext('2d');ctx.fillStyle=grad(ctx,0,0,w,hei,h.color+'38','#101a28');ctx.fillRect(0,0,w,hei);ring(ctx,w*.54,hei*.58,w*.38,h.color+'40',1);line(ctx,8,hei-3,w-8,hei-3,h.color+'aa',2);ctx.save();ctx.translate(w*.45,hei*1.55);drawFighter(ctx,fighter(h.id,0,1),h.id,hei/140);ctx.restore();return c.toDataURL();}
let lastHUD='';function updateHUD(){const g=game;if(!g)return;$('pName').innerHTML=g.p.h.name+' <small>ТЫ</small>';$('eName').textContent=g.e.h.name;$('pHealth').style.width=(g.p.hp/g.p.maxHp*100)+'%';$('eHealth').style.width=(g.e.hp/g.e.maxHp*100)+'%';$('pMeter').style.width=g.p.meter+'%';$('eMeter').style.width=g.e.meter+'%';$('pRounds').textContent=(g.rounds[0]>0?'●':'○')+' '+(g.rounds[0]>1?'●':'○');$('eRounds').textContent=(g.rounds[1]>0?'●':'○')+' '+(g.rounds[1]>1?'●':'○');$('timer').textContent=g.mode==='training'?'∞':Math.max(0,Math.ceil(g.clock));$('roundLabel').textContent=g.mode==='training'?'ТРЕНИРОВКА':'РАУНД '+(g.rounds[0]+g.rounds[1]+1);$('arenaName').textContent=g.arena.name.toUpperCase();$('modifierName').textContent=(g.mode==='arcade'?'БОЙ '+(g.run+1)+' · ':'')+g.mod.name;$('specialCD').classList.toggle('hidden',g.p.cd<=0);$('specialCD').textContent=Math.ceil(g.p.cd);$('ultCD').classList.toggle('hidden',g.p.meter>=99.9);$('ultCD').textContent=Math.floor(g.p.meter)+'%';
let toast='',sub='';if(g.phase==='intro'){toast=g.phaseTimer>.45?'РАУНД '+(g.rounds[0]+g.rounds[1]+1):'В БОЙ';sub=g.mode==='training'?'ТРЕНИРОВКА':g.p.h.name+' × '+g.e.h.name;}if(g.phase==='roundEnd'){toast=g.roundWinner<0?'НИЧЬЯ':g.roundWinner===0?'ТВОЙ РАУНД':'РАУНД СОПЕРНИКА';sub=g.roundWinner===0?'ПРОДОЛЖАЙ ДАВИТЬ':'СМЕНИ ТАКТИКУ';}const key=toast+sub;if(key!==lastHUD){lastHUD=key;$('toast').classList.toggle('hidden',!toast);$('toast').innerHTML=toast+'<small>'+sub+'</small>';}}
function showScreen(name){state=name;['home','select','game'].forEach(n=>$(n).classList.toggle('hidden',n!==name));$('modal').classList.add('hidden');clearInput();last=performance.now();acc=0;}
function startMatch(continuing=false){unlockAudio();if(!continuing){stageBag=shuffle(arenas.map(a=>a.id));opponentBag=[];}const arena=continuing?nextStage():settings.arena<0?nextStage():settings.arena;if(!continuing&&settings.arena>=0)stageBag=stageBag.filter(i=>i!==arena);const run=continuing&&game?game.run+1:0;game=createGame(settings.hero,nextOpponent(),arena,settings.mode,settings.difficulty,run);if(settings.mode==='training')game.p.meter=100;cacheKey='';showScreen('game');persist();}
function modal(title,eyebrow,body,buttons){$('modalCard').innerHTML='<div class="eyebrow">'+eyebrow+'</div><h2>'+title+'</h2>'+body;buttons.forEach(b=>{const el=document.createElement('button');el.className=b.primary?'primary':'secondary';el.textContent=b.text;el.onclick=b.fn;$('modalCard').append(el);});$('modal').classList.remove('hidden');clearInput();}
function pause(){if(state!=='game'||!game||game.phase==='finished'||game.paused)return;game.paused=true;modal('Пауза','RIFT // DUEL','<p>Бой остановлен. Продолжи, когда будешь готов.</p>',[{text:'ПРОДОЛЖИТЬ',primary:true,fn:resume},{text:'Начать матч заново',fn:()=>startMatch(false)},{text:'Выбор бойца',fn:openSelect}]);}
function resume(){if(game)game.paused=false;$('modal').classList.add('hidden');clearInput();last=performance.now();acc=0;unlockAudio();}
function showResult(){const win=game.rounds[0]>=2;if(win){settings.best=Math.max(settings.best,game.mode==='arcade'?game.run+1:1);persist();sfx('win');}const body='<p>'+game.p.h.name+' <b>'+game.rounds[0]+' : '+game.rounds[1]+'</b> '+game.e.h.name+'</p><p>'+Math.round(game.p.dealt)+' урона в последнем раунде'+(game.mode==='arcade'?'<br>Серия: '+(game.run+(win?1:0))+' · Рекорд: '+settings.best:'')+'</p>';const buttons=[];if(win&&game.mode==='arcade')buttons.push({text:'СЛЕДУЮЩИЙ РАЗЛОМ　→',primary:true,fn:()=>startMatch(true)});else buttons.push({text:'ЕЩЁ ОДИН БОЙ　→',primary:true,fn:()=>startMatch(false)});buttons.push({text:'Выбрать другого бойца',fn:openSelect});modal(win?'ПОБЕДА':'ПОРАЖЕНИЕ',win?'РАЗЛОМ ПОКОРЁН':'ЕЩЁ НЕ КОНЕЦ',body,buttons);}
function help(){modal('Твой первый бой','УПРАВЛЕНИЕ','<div class="help-grid"><p><b>Левый палец:</b> джойстик для движения; вверх — прыжок, вниз — присесть.</p><p><b>Правый палец:</b> удар рукой, ногой и уникальная сила. Удерживай кнопку для повторных атак. Сила восстанавливается несколько секунд.</p><p><b>Блок</b> нужно держать. <b>Рывок</b> сокращает дистанцию. <b>Супер</b> доступен при 100% энергии и бьёт в пределах средней дистанции.</p><p>Подойди ближе перед ударом. Матч — до двух выигранных раундов. Горизонтальный экран удобнее, вертикальный тоже поддерживается.</p><p class="muted">Клавиатура: A/D или ←/→, W/↑ — прыжок, S/↓ — присесть; J/K/L — атаки, Shift — блок, Space — рывок, U — супер, Esc — пауза.</p></div>',[{text:'ПОПРОБОВАТЬ',primary:true,fn:()=>{settings.mode='training';startMatch();}},{text:'Понятно',fn:()=>$('modal').classList.add('hidden')}]);}
function refreshSelection(){const h=roster[settings.hero];$('heroClass').textContent=h.title;$('heroName').textContent=h.name;$('heroSkill').innerHTML='<b>'+h.skill+'</b> · '+h.desc;$('heroStats').textContent='Здоровье '+h.hp+' · Скорость '+Math.round(h.speed)+' · Перезарядка '+h.cd.toFixed(1)+' с';document.querySelectorAll('.fighter-card').forEach(b=>{const active=+b.dataset.hero===h.id;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.querySelectorAll('.arena-card').forEach(b=>b.classList.toggle('active',+b.dataset.arena===settings.arena));document.querySelectorAll('.mode-row').forEach(b=>b.classList.toggle('active',b.dataset.mode===settings.mode));$('selectionSummary').textContent=h.name+' · '+(settings.arena<0?'Случайная арена':arenas[settings.arena].name);const c=$('heroPreview'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.save();ctx.translate(c.width*.46,c.height*.93);drawFighter(ctx,fighter(h.id,0,1),0,1.02);ctx.restore();persist();}
function openSelect(){if(game)game.paused=true;showScreen('select');refreshSelection();}
function buildSelection(){for(const h of roster){const b=document.createElement('button');b.className='fighter-card';b.dataset.hero=h.id;b.setAttribute('aria-label',h.name+': '+h.skill);const img=document.createElement('img');img.src=portrait(h);img.alt='';b.append(img);const n=document.createElement('b');n.textContent=h.name;b.append(n);const small=document.createElement('small');small.textContent=String(h.id+1).padStart(2,'0')+' / '+['КЛИНОК','МАГ','ТЕХНИК','ТЕНЬ','ТИТАН','СЛЕДОПЫТ','МИСТИК'][h.body];b.append(small);b.onclick=()=>{settings.hero=h.id;refreshSelection();sfx('ui');};$('fighters').append(b);}
const random=document.createElement('button');random.className='arena-card';random.dataset.arena=-1;random.innerHTML='<div style="height:80px;display:grid;place-items:center;font-size:35px;color:var(--cyan)">∞</div><b>Случайная арена</b>';random.onclick=()=>{settings.arena=-1;refreshSelection();};$('arenas').append(random);
for(const a of arenas){const b=document.createElement('button');b.className='arena-card';b.dataset.arena=a.id;const c=document.createElement('canvas');c.width=270;c.height=155;drawArena(c.getContext('2d'),270,155,a,0,0);const im=document.createElement('img');im.src=c.toDataURL();im.alt='';b.append(im);const n=document.createElement('b');n.textContent=String(a.id+1).padStart(2,'0')+' / '+a.name;b.append(n);b.onclick=()=>{settings.arena=a.id;refreshSelection();};$('arenas').append(b);}
refreshSelection();}
function renderHome(t){const c=$('homeArt'),{w:W,h:H,d}=fitCanvas(c),ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);drawArena(ctx,W,H,arenas[0],19,t*.25);const landscape=W>H,sc=Math.min(W/(landscape?850:455),H/(landscape?480:620)),floor=landscape?H*.89:H*.66;ctx.save();ctx.globalAlpha=.5;ring(ctx,W*.50,floor-95*sc,125*sc,'#7dfde029',1);ring(ctx,W*.50,floor-95*sc,137*sc,'#7dfde017',1);ctx.restore();for(let i=0;i<2;i++){let x=landscape?W*(i?.67:.50):W*(i?.73:.29);ctx.save();ctx.translate(x,floor);ellipse(ctx,0,4,sc*60,sc*11,'#00000088');drawFighter(ctx,fighter(i?3:0,0,i?-1:1),t+i*2,sc*(i?.96:1.02));ctx.restore();}}
const keyActions={KeyJ:'light',KeyK:'heavy',KeyL:'special',KeyU:'ult',ShiftLeft:'block',ShiftRight:'block'};
function updateMovement(){const st=input.stick;const kx=(input.keys.has('KeyD')||input.keys.has('ArrowRight')?1:0)-(input.keys.has('KeyA')||input.keys.has('ArrowLeft')?1:0);input.x=kx||(st?st.dx:0);input.crouch=input.keys.has('KeyS')||input.keys.has('ArrowDown')||Boolean(st&&st.dy>.55);input.held=new Set([...input.pointers.values(),...[...input.keys].map(k=>keyActions[k]).filter(Boolean)]);document.querySelectorAll('.action').forEach(b=>b.classList.toggle('pressed',input.held.has(b.dataset.action)));}
const stick=$('stick');function moveStick(e){if(!input.stick||input.stick.id!==e.pointerId)return;const r=stick.getBoundingClientRect(),max=r.width*.33,dx=clamp((e.clientX-r.left-r.width/2)/max,-1,1),dy=clamp((e.clientY-r.top-r.height/2)/max,-1,1);input.stick.dx=Math.abs(dx)>.18?dx:0;input.stick.dy=dy;$('knob').style.transform='translate('+dx*max+'px,'+dy*max+'px)';if(dy<-.55&&!input.jumped&&game&&!game.paused){doAction(game.p,'jump');input.jumped=true;}if(dy>-.25)input.jumped=false;updateMovement();}
stick.addEventListener('pointerdown',e=>{if(state!=='game'||!game||game.paused||input.stick)return;e.preventDefault();input.stick={id:e.pointerId,dx:0,dy:0};try{stick.setPointerCapture(e.pointerId);}catch(_){}moveStick(e);},{passive:false});stick.addEventListener('pointermove',e=>{if(input.stick&&input.stick.id===e.pointerId){e.preventDefault();moveStick(e);}},{passive:false});
function endPointer(e){if(input.stick&&input.stick.id===e.pointerId){input.stick=null;input.jumped=false;$('knob').style.transform='';}input.pointers.delete(e.pointerId);updateMovement();}
for(const name of ['pointerup','pointercancel','lostpointercapture']){stick.addEventListener(name,endPointer);window.addEventListener(name,endPointer);}
document.querySelectorAll('.action').forEach(b=>{b.addEventListener('pointerdown',e=>{if(state!=='game'||!game||game.paused)return;e.preventDefault();try{b.setPointerCapture(e.pointerId);}catch(_){}const a=b.dataset.action;input.pointers.set(e.pointerId,a);updateMovement();if(a!=='block')doAction(game.p,a);unlockAudio();},{passive:false});b.addEventListener('lostpointercapture',endPointer);});
window.addEventListener('keydown',e=>{if(e.code==='Escape'&&state==='game'){e.preventDefault();game.paused?resume():pause();return;}if(state!=='game'||!game||game.paused)return;const valid=['KeyA','KeyD','KeyW','KeyS','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space',...Object.keys(keyActions)];if(!valid.includes(e.code))return;e.preventDefault();if(!e.repeat){input.keys.add(e.code);updateMovement();if(e.code==='KeyW'||e.code==='ArrowUp')doAction(game.p,'jump');else if(e.code==='Space')doAction(game.p,'dash');else if(keyActions[e.code]&&keyActions[e.code]!=='block')doAction(game.p,keyActions[e.code]);}});
window.addEventListener('keyup',e=>{input.keys.delete(e.code);updateMovement();});window.addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(state==='game')pause();}last=performance.now();acc=0;});$('game').addEventListener('contextmenu',e=>e.preventDefault());$('game').addEventListener('touchmove',e=>e.preventDefault(),{passive:false});
$('chooseBtn').onclick=openSelect;$('quickBtn').onclick=()=>{settings.mode='quick';startMatch();};$('helpBtn').onclick=help;$('backHome').onclick=()=>showScreen('home');$('fightBtn').onclick=()=>startMatch();$('pauseBtn').onclick=pause;$('randomBtn').onclick=()=>{settings.hero=Math.floor(Math.random()*37);refreshSelection();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.classList.toggle('active',t===b));['fighters','arenas','modes'].forEach(t=>$(t).classList.toggle('hidden',t!==b.dataset.tab));});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{settings.mode=b.dataset.mode;refreshSelection();});$('difficulty').onchange=e=>settings.difficulty=+e.target.value;$('sound').value=settings.sound?'1':'0';$('sound').onchange=e=>{settings.sound=e.target.value==='1';unlockAudio();persist();};$('effects').value=settings.effects?'1':'0';$('effects').onchange=e=>{settings.effects=e.target.value==='1';persist();};
function frame(now){const dt=Math.min(.07,Math.max(0,(now-last)/1000));last=now;time+=dt;if(state==='game'&&game){if(!game.paused){acc=Math.min(acc+dt,.1);while(acc>=1/60){step(game,1/60);acc-=1/60;}}renderBattle();}else if(state==='home'&&++homeFrame%2===0)renderHome(time);requestAnimationFrame(frame);}
