if(new URLSearchParams(location.search).has('test'))window.__RIFT_TEST__={roster,arenas,settings,mods,createGame,step,doAction,special,damage,melee,fighter,nextStage,getGame:()=>game,getInput:()=>({x:input.x,crouch:input.crouch,held:[...input.held],pointers:input.pointers.size}),getState:()=>state,startMatch,openSelect,pause,resume,clearInput,renderBattle,drawArena,drawFighter,setStageBag:v=>stageBag=v};
try{buildSelection();renderHome(0);last=performance.now();requestAnimationFrame(frame);}catch(e){console.error(e);const box=document.createElement('div');box.className='fatal-error';box.textContent='Не удалось запустить игру. Открой страницу в актуальном Safari или Chrome. Ошибка: '+e.message;document.body.append(box);}
